pragma solidity 0.8.36;
contract CompositeGettersFallback { struct Record { uint16 small; uint256 big; bytes payload; uint256[] omittedArray; mapping(uint256 => uint256) omittedMapping; } mapping(address => Record[]) public records; mapping(string => uint256) public named; bytes public blob; uint256[] public values; fallback(bytes calldata input) external returns (bytes memory) { return input; } }
